//! Secret key types.
//!
//! Every type is generated by `secret_type!`: a fixed-size byte array that
//! zeroizes on drop and has no `Clone`, `Copy`, `Debug`, `Display`,
//! `Serialize` or `PartialEq`. Equality is only available through
//! [`subtle::ConstantTimeEq`]. Raw bytes are reachable only inside the crate,
//! with narrow exceptions for a binding: the constructors
//! [`PrfOutput::from_slice`], [`KekDevPin::from_slice`] and
//! [`ExportWrapKey::from_slice`] (exact length, bytes that come from outside
//! the core), and [`ExportWrapKey::to_bytes`], the one accessor: `K_exp` opens
//! only the wrapped content key of one export file and has to cross between
//! the worker that ran Argon2id and the one that holds the vault.

use crate::error::{Error, InputError};
use crate::rng::SecureRng;

/// Defines a secret key type of `$len` bytes.
macro_rules! secret_type {
    ($(#[$meta:meta])* $name:ident, $len:expr) => {
        $(#[$meta])*
        #[derive(zeroize::Zeroize, zeroize::ZeroizeOnDrop)]
        pub struct $name([u8; $len]);

        impl $name {
            /// Length in bytes.
            pub const LEN: usize = $len;

            /// Takes ownership of the bytes. Used by derivations and parsers.
            #[allow(dead_code)] // first used by later tasks
            pub(crate) fn from_array(bytes: [u8; $len]) -> Self {
                Self(bytes)
            }

            /// Takes the bytes out of `src` and wipes `src`. Unlike
            /// `from_array`, no by-value copy of the key is left in the
            /// caller's frame: the key is written straight into the new value.
            #[allow(dead_code)] // used by the code readers only
            pub(crate) fn from_array_wiping(src: &mut [u8; $len]) -> Self {
                let mut key = Self([0u8; $len]);
                key.0.copy_from_slice(src);
                zeroize::Zeroize::zeroize(src);
                key
            }

            /// Draws fresh bytes from `rng`.
            #[allow(dead_code)] // first used by later tasks
            pub(crate) fn random<R: SecureRng>(rng: &mut R) -> Self {
                let mut bytes = [0u8; $len];
                rng.fill(&mut bytes);
                let key = Self(bytes);
                zeroize::Zeroize::zeroize(&mut bytes);
                key
            }

            /// Read access to the raw bytes. Never public.
            #[allow(dead_code)] // first used by later tasks
            pub(crate) fn expose(&self) -> &[u8; $len] {
                &self.0
            }

            /// Builds a key from fixed bytes. Only for tests and vector
            /// runners; absent from release builds.
            #[cfg(feature = "test-support")]
            pub fn from_test_bytes(bytes: [u8; $len]) -> Self {
                Self(bytes)
            }
        }

        impl subtle::ConstantTimeEq for $name {
            fn ct_eq(&self, other: &Self) -> subtle::Choice {
                subtle::ConstantTimeEq::ct_eq(self.0.as_slice(), other.0.as_slice())
            }
        }
    };
}

secret_type!(
    /// Vault key (VK).
    VaultKey,
    32
);
secret_type!(
    /// Item key (IK).
    ItemKey,
    32
);
secret_type!(
    /// Key-encryption key (KEK) for one unlock method.
    Kek,
    32
);
secret_type!(
    /// The hardware-bound secret `KEK_dev_pin` of the mobile PIN method
    /// (Fase 1 § 7.4), as released by the platform keystore.
    KekDevPin,
    32
);
secret_type!(
    /// Recovery key (RK).
    RecoveryKey,
    32
);
secret_type!(
    /// Secret key (SK), the second factor mixed into the OPAQUE input.
    SecretKey,
    16
);
secret_type!(
    /// OPAQUE export key.
    ExportKey,
    64
);
secret_type!(
    /// Output of the WebAuthn PRF extension.
    PrfOutput,
    32
);
secret_type!(
    /// Seed derived from a PRF output.
    PrfSeed,
    32
);
secret_type!(
    /// Key for the checkpoint MAC and item tags.
    KHead,
    32
);
secret_type!(
    /// Key for tombstones.
    KDel,
    32
);
secret_type!(
    /// Key for the manifest.
    KMeta,
    32
);
secret_type!(
    /// Seed for the authentication key pair.
    AuthSeed,
    32
);
secret_type!(
    /// Content key of an export file (EK).
    ExportContentKey,
    32
);
secret_type!(
    /// `K_exp`, the key that wraps the content key of an export file
    /// (Fase 1 § 6.4). It is the result of the slow Argon2id step, so a
    /// binding can run that step in a short-lived worker and hand this key
    /// to the worker that holds the vault. It is not a vault key.
    ExportWrapKey,
    32
);

/// The exact-length check of the release constructors below.
fn exact_len<const N: usize>(bytes: &[u8]) -> Result<[u8; N], Error> {
    use core::cmp::Ordering;
    match bytes.len().cmp(&N) {
        Ordering::Less => Err(Error::InvalidInput(InputError::TooShort)),
        Ordering::Greater => Err(Error::InvalidInput(InputError::TooLong)),
        Ordering::Equal => bytes
            .try_into()
            .map_err(|_| Error::InvalidInput(InputError::TooShort)),
    }
}

impl PrfOutput {
    /// Takes the 32 bytes of a WebAuthn PRF output that an authenticator
    /// returned (the client got them from `getClientExtensionResults`). Any
    /// other length is `input_too_short` or `input_too_long`.
    ///
    /// This is the one way a PRF output enters the core in a release build,
    /// for the passkey unlock method. The caller wipes its own copy.
    pub fn from_slice(bytes: &[u8]) -> Result<Self, Error> {
        let mut arr = exact_len::<32>(bytes)?;
        Ok(Self::from_array_wiping(&mut arr))
    }
}

impl KekDevPin {
    /// Takes the 32 bytes that the platform keystore released for the mobile
    /// PIN method (Fase 1 § 7.4). Any other length is `input_too_short` or
    /// `input_too_long`. The caller wipes its own copy.
    pub fn from_slice(bytes: &[u8]) -> Result<Self, Error> {
        let mut arr = exact_len::<32>(bytes)?;
        Ok(Self::from_array_wiping(&mut arr))
    }
}

impl ExportWrapKey {
    /// Takes the 32 bytes of a `K_exp` that [`crate::export::export_wrap_key`]
    /// made in another worker. Any other length is `input_too_short` or
    /// `input_too_long`. The caller wipes its own copy.
    pub fn from_slice(bytes: &[u8]) -> Result<Self, Error> {
        let mut arr = exact_len::<32>(bytes)?;
        Ok(Self::from_array_wiping(&mut arr))
    }

    /// The 32 bytes, for the one hand-over between the worker that ran
    /// Argon2id and the worker that holds the vault. `K_exp` only opens the
    /// wrapped content key of the one export file it was made for; it is not
    /// a vault key. The caller wipes the copy after it has sent it.
    pub fn to_bytes(&self) -> zeroize::Zeroizing<[u8; 32]> {
        zeroize::Zeroizing::new(*self.expose())
    }
}

impl VaultKey {
    /// A fresh random vault key.
    pub fn generate<R: SecureRng>(rng: &mut R) -> Self {
        Self::random(rng)
    }
}

impl RecoveryKey {
    /// A fresh random recovery key.
    pub fn generate<R: SecureRng>(rng: &mut R) -> Self {
        Self::random(rng)
    }
}

impl SecretKey {
    /// A fresh random secret key.
    pub fn generate<R: SecureRng>(rng: &mut R) -> Self {
        Self::random(rng)
    }
}
